import Link from "next/link";
import { ArrowRight, Sparkles } from "lucide-react";
import { heroFeatures } from "../../data/home-data";
import { HERO_IMAGE, serif, wrap } from "../../lib/constants";

export function Hero() {
  return (
    <section className={`${wrap} pt-2`}>
      <div className="relative isolate overflow-hidden rounded-3xl bg-[#14132a] text-white">
        {/* Imagen de fondo */}
        <div
          aria-hidden
          className="absolute inset-0 -z-10 bg-cover bg-center"
          style={{
            backgroundImage: `url(${HERO_IMAGE}), radial-gradient(circle at 75% 25%, color-mix(in srgb, var(--color-primario) 55%, transparent), transparent 50%), linear-gradient(135deg, #1b1b2f 0%, #0d0c1d 100%)`,
          }}
        />
        {/* Degradado para legibilidad del texto */}
        <div
          aria-hidden
          className="absolute inset-0 -z-10 bg-gradient-to-r from-[#14132a]/85 via-[#14132a]/45 to-transparent"
        />

        <div className="relative px-6 pb-36 pt-12 sm:px-10 md:pb-44 md:pt-16 lg:px-14">
          <p className="text-[11px] font-semibold uppercase tracking-[0.25em] text-white/80">
            Descubre tu ciudad
          </p>
          <h1
            className={`${serif} m-0 mt-4 max-w-xl text-5xl font-normal leading-[1.05] tracking-tight text-white sm:text-6xl lg:text-7xl`}
          >
            Todas tus compras
            <span className="block italic text-[color-mix(in_srgb,var(--color-descuento)_60%,white)]">
              a un solo click.
            </span>
          </h1>

          <p className="mt-6 max-w-sm text-sm leading-7 text-white/85 sm:text-base">
            Productos y negocios únicos de Guayaquil, reunidos en un solo
            lugar. Todo lo que buscas, más cerca de lo que imaginas.
          </p>

          <div className="mt-8 flex flex-wrap items-center gap-3">
            <Link
              href="/explorar"
              className="inline-flex items-center gap-2 rounded-lg bg-[var(--color-primario)] px-7 py-3.5 text-xs font-bold uppercase tracking-wider text-[var(--color-sobre-primario)] shadow-lg transition hover:opacity-90"
            >
              Comprar ahora <ArrowRight size={15} />
            </Link>
            <Link
              href="/tiendas"
              className="inline-flex items-center gap-2 rounded-lg border border-white/60 bg-white/5 px-7 py-3.5 text-xs font-bold uppercase tracking-wider backdrop-blur transition hover:bg-white/15"
            >
              Explorar tiendas
            </Link>
          </div>

          <ul className="mt-10 hidden flex-wrap gap-x-8 gap-y-3 sm:flex">
            {heroFeatures.map(({ icon: Icon, title, detail }) => (
              <li key={title} className="flex items-center gap-2.5">
                <Icon size={20} className="text-white/90" />
                <span className="text-[10px] leading-tight">
                  <span className="block font-semibold">{title}</span>
                  <span className="text-white/70">{detail}</span>
                </span>
              </li>
            ))}
          </ul>
        </div>

        {/* Sello flotante */}
        <div
          className="zentrall-float absolute right-8 top-8 hidden h-28 w-28 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--color-primario)_55%,#14132a)] shadow-xl md:flex lg:right-16 lg:top-10"
          style={{ ["--rot" as string]: "6deg" }}
        >
          <div className="flex h-[88%] w-[88%] flex-col items-center justify-center rounded-full border border-white/50 text-center">
            <span className="text-[8px] font-semibold uppercase tracking-widest">
              Nueva
            </span>
            <span className={`${serif} text-sm italic leading-tight`}>
              Colección
              <br />
              Local
            </span>
            <Sparkles size={12} className="mt-1" />
          </div>
        </div>

        {/* Borde inferior líquido animado */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-x-0 bottom-0 h-20 overflow-hidden md:h-28"
        >
          <svg
            viewBox="0 0 2880 120"
            preserveAspectRatio="none"
            className="zentrall-wave-b absolute bottom-0 left-0 h-full w-[200%]"
          >
            <path
              d="M0,40 C180,95 540,95 720,40 C900,-15 1260,-15 1440,40 C1620,95 1980,95 2160,40 C2340,-15 2700,-15 2880,40 L2880,120 L0,120 Z"
              style={{
                fill: "color-mix(in srgb, var(--color-fondo) 45%, transparent)",
              }}
            />
          </svg>
          <svg
            viewBox="0 0 2880 120"
            preserveAspectRatio="none"
            className="zentrall-wave-a absolute bottom-0 left-0 h-[78%] w-[200%]"
          >
            <path
              d="M0,60 C240,115 480,115 720,60 C960,5 1200,5 1440,60 C1680,115 1920,115 2160,60 C2400,5 2640,5 2880,60 L2880,120 L0,120 Z"
              style={{ fill: "var(--color-fondo)" }}
            />
          </svg>
        </div>
      </div>
    </section>
  );
}